b_except_a as (

    select * from b
    {{ dbt.except() }}
    select * from a

),

all_records as (

    select
        *,
        1 as in_a,
        1 as in_b
    from a_intersect_b

    union all

    select
        *,
        1 as in_a,
        0 as in_b
    from a_except_b

    union all

    select
        *,
        0 as in_a,
        1 as in_b
    from b_except_a

),

{%- if summarize %}

summary_stats as (
    select
        in_a,
        in_b,
        count(*) as count
    from all_records
    group by in_a, in_b
),

final as (

    select
        *,
        round(100.0 * count / sum(count) over (), 2) as percent_of_total
    from summary_stats

)

{%- else %}

final as (

    select *
    from all_records
    where not (in_a = 1 and in_b = 1)

)

{%- endif %}

select * from final
{%- if limit and not summarize %}
order by {{ primary_key ~ ", " if primary_key is not none }} in_a desc, in_b desc
offset 0 rows fetch next {{ limit }} rows only
{%- endif %}

{% endmacro %}

